-- Deliberate member selection, role and lost-update proof; synthetic rows roll back.
begin;
create temporary table portfolio_checks(label text primary key);
create function pg_temp.portfolio_ok(label text,value boolean)returns void language plpgsql security definer as $$begin
 if value is distinct from true then raise exception 'PORTFOLIO FAIL: %',label;end if;insert into pg_temp.portfolio_checks values(label);end $$;
create function pg_temp.portfolio_denied(label text,statement text,message text)returns void language plpgsql as $$declare e text;begin
 begin execute statement;exception when others then e:=sqlerrm;end;
 if e is null or position(message in e)=0 then raise exception 'PORTFOLIO FAIL: % wrong denial: %',label,coalesce(e,'accepted');end if;perform pg_temp.portfolio_ok(label,true);end $$;
insert into auth.users(id,email,is_anonymous)values
 ('ca100601-0000-4000-8000-000000000001','portfolio-owner@fixture.invalid',false),
 ('ca100601-0000-4000-8000-000000000002','portfolio-member@fixture.invalid',false),
 ('ca100601-0000-4000-8000-000000000003','portfolio-outsider@fixture.invalid',false);
create temporary table portfolio_fixture as select org_id org from memberships where user_id='ca100601-0000-4000-8000-000000000001';
grant select on portfolio_fixture to service_role;
insert into memberships(org_id,user_id,role)select org,'ca100601-0000-4000-8000-000000000002','agent'from portfolio_fixture;
insert into listings(id,org_id,agent_id,address,details)select ('ca100602-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,org,case when n=2 then 'ca100601-0000-4000-8000-000000000001'::uuid else 'ca100601-0000-4000-8000-000000000002'::uuid end,'Synthetic portfolio '||n,'{"allow_indexing":true}'from portfolio_fixture cross join generate_series(1,4)n;
insert into render_jobs(id,listing_id,status)select id,id,'completed'from listings where id::text like 'ca100602-%';
insert into renders(job_id,listing_id,slug,duration_s,published_at)select id,id,'fixture-portfolio-'||right(id::text,12),10,case when right(id::text,1)='4'then null else now()end from listings where id::text like 'ca100602-%';
select pg_temp.portfolio_ok('selection table denies ordinary reads and writes',not has_table_privilege('authenticated','member_portfolios','SELECT')and not has_table_privilege('anon','member_portfolios','INSERT'));
select pg_temp.portfolio_ok('selection helpers service only',not has_function_privilege('authenticated','read_member_portfolio(uuid,uuid)','EXECUTE')and not has_function_privilege('anon','save_member_portfolio(uuid,uuid,bigint,uuid[])','EXECUTE'));
set local role service_role;
select pg_temp.portfolio_ok('new member selection starts empty without inherited workspace listings',read_member_portfolio('ca100601-0000-4000-8000-000000000002',(select org from portfolio_fixture))->'listing_ids'='[]'and read_member_portfolio('ca100601-0000-4000-8000-000000000002',(select org from portfolio_fixture))->>'revision'='0');
select save_member_portfolio('ca100601-0000-4000-8000-000000000002',(select org from portfolio_fixture),0,array['ca100602-0000-4000-8000-000000000001'::uuid]);
select pg_temp.portfolio_ok('explicit save publishes only own selected listing',(select listing_ids=array['ca100602-0000-4000-8000-000000000001'::uuid]and revision=1 and id<>user_id and id<>org_id from member_portfolios where user_id='ca100601-0000-4000-8000-000000000002'));
select save_member_portfolio('ca100601-0000-4000-8000-000000000002',(select org from portfolio_fixture),0,array['ca100602-0000-4000-8000-000000000001'::uuid]);
select pg_temp.portfolio_ok('matching lost receipt replay preserves revision',(select revision=1 from member_portfolios where user_id='ca100601-0000-4000-8000-000000000002'));
select pg_temp.portfolio_denied('stale different selection conflicts','select save_member_portfolio(''ca100601-0000-4000-8000-000000000002'',(select org from portfolio_fixture),0,''{}'')','RP409');
select pg_temp.portfolio_denied('other member listing cannot be selected','select save_member_portfolio(''ca100601-0000-4000-8000-000000000002'',(select org from portfolio_fixture),1,array[''ca100602-0000-4000-8000-000000000002''::uuid])','RP409');
select pg_temp.portfolio_denied('unpublished listing cannot be selected','select save_member_portfolio(''ca100601-0000-4000-8000-000000000002'',(select org from portfolio_fixture),1,array[''ca100602-0000-4000-8000-000000000004''::uuid])','RP409');
select pg_temp.portfolio_denied('duplicates refused','select save_member_portfolio(''ca100601-0000-4000-8000-000000000002'',(select org from portfolio_fixture),1,array[''ca100602-0000-4000-8000-000000000001''::uuid,''ca100602-0000-4000-8000-000000000001''::uuid])','RP400');
select pg_temp.portfolio_denied('null element refused','select save_member_portfolio(''ca100601-0000-4000-8000-000000000002'',(select org from portfolio_fixture),1,array[null::uuid])','RP400');
select pg_temp.portfolio_denied('outsider cannot read workspace selection','select read_member_portfolio(''ca100601-0000-4000-8000-000000000003'',(select org from portfolio_fixture))','RP403');
select save_member_portfolio('ca100601-0000-4000-8000-000000000002',(select org from portfolio_fixture),1,'{}');
select pg_temp.portfolio_ok('deliberate clear empties selection with next revision',(select cardinality(listing_ids)=0 and revision=2 from member_portfolios where user_id='ca100601-0000-4000-8000-000000000002'));
reset role;
update listings set details='{}'where id='ca100602-0000-4000-8000-000000000003';
set local role service_role;
select pg_temp.portfolio_denied('absent discovery consent refused','select save_member_portfolio(''ca100601-0000-4000-8000-000000000002'',(select org from portfolio_fixture),2,array[''ca100602-0000-4000-8000-000000000003''::uuid])','RP409');
reset role;
update listings set details='{"allow_indexing":"true"}'where id='ca100602-0000-4000-8000-000000000003';
insert into listing_client_contacts(listing_id,org_id,enabled)select 'ca100602-0000-4000-8000-000000000003',org,true from portfolio_fixture;
set local role service_role;
select pg_temp.portfolio_denied('client delivery listing refused','select save_member_portfolio(''ca100601-0000-4000-8000-000000000002'',(select org from portfolio_fixture),2,array[''ca100602-0000-4000-8000-000000000003''::uuid])','RP409');
reset role;
update listing_client_contacts set enabled=false where listing_id='ca100602-0000-4000-8000-000000000003';
update listings set sold_at=now()where id='ca100602-0000-4000-8000-000000000003';
set local role service_role;
select pg_temp.portfolio_denied('sold listing refused','select save_member_portfolio(''ca100601-0000-4000-8000-000000000002'',(select org from portfolio_fixture),2,array[''ca100602-0000-4000-8000-000000000003''::uuid])','RP409');
reset role;
update listings set sold_at=null,status='archived'where id='ca100602-0000-4000-8000-000000000003';
set local role service_role;
select pg_temp.portfolio_denied('archived listing refused','select save_member_portfolio(''ca100601-0000-4000-8000-000000000002'',(select org from portfolio_fixture),2,array[''ca100602-0000-4000-8000-000000000003''::uuid])','RP409');
reset role;
update listings set status='ready',deleted_at=now()where id='ca100602-0000-4000-8000-000000000003';
set local role service_role;
select pg_temp.portfolio_denied('deleted listing refused','select save_member_portfolio(''ca100601-0000-4000-8000-000000000002'',(select org from portfolio_fixture),2,array[''ca100602-0000-4000-8000-000000000003''::uuid])','RP409');
reset role;
update listings set deleted_at=null where id='ca100602-0000-4000-8000-000000000003';
update renders set published_at=now()where listing_id='ca100602-0000-4000-8000-000000000003';
update memberships set role='marketing'where org_id=(select org from portfolio_fixture)and user_id='ca100601-0000-4000-8000-000000000002';
set local role service_role;
select pg_temp.portfolio_denied('marketing role cannot publish','select save_member_portfolio(''ca100601-0000-4000-8000-000000000002'',(select org from portfolio_fixture),2,''{}'')','RP403');
reset role;
update memberships set role='agent'where org_id=(select org from portfolio_fixture)and user_id='ca100601-0000-4000-8000-000000000002';
set local role service_role;
select save_member_portfolio('ca100601-0000-4000-8000-000000000002',(select org from portfolio_fixture),2,array['ca100602-0000-4000-8000-000000000003'::uuid]);
select pg_temp.portfolio_ok('native string true consent accepted',(select revision=3 from member_portfolios where user_id='ca100601-0000-4000-8000-000000000002'));
reset role;
delete from memberships where org_id=(select org from portfolio_fixture)and user_id='ca100601-0000-4000-8000-000000000002';
set local role service_role;
select pg_temp.portfolio_denied('removed member cannot read','select read_member_portfolio(''ca100601-0000-4000-8000-000000000002'',(select org from portfolio_fixture))','RP403');
select pg_temp.portfolio_denied('removed member cannot save','select save_member_portfolio(''ca100601-0000-4000-8000-000000000002'',(select org from portfolio_fixture),3,''{}'')','RP403');
reset role;
insert into memberships(org_id,user_id,role)select org,'ca100601-0000-4000-8000-000000000002','agent'from portfolio_fixture;
set local role service_role;
select prepare_account_deletion('ca100601-0000-4000-8000-000000000002','fixture-uploads','fixture-renders');
select pg_temp.portfolio_denied('pending deletion cannot read','select read_member_portfolio(''ca100601-0000-4000-8000-000000000002'',(select org from portfolio_fixture))','RP403');
select pg_temp.portfolio_denied('pending deletion cannot save','select save_member_portfolio(''ca100601-0000-4000-8000-000000000002'',(select org from portfolio_fixture),3,''{}'')','RP403');
reset role;
select count(*)as portfolio_assertions from portfolio_checks;
select 'PASS: member portfolio SQL assertions; all fixtures rolled back.';
rollback;
